variants.question:
다음 C 함수에서 c++가 실행되는 횟수를 n의 식으로 세고, 가장 빨리 커지는 항만 남겨 빅오 표기로 나타낸 것은? (단, n은 1보다 큰 정수다)

[코드]
int work(int n) {
    int c = 0, i, j, k;
    for (i = 0; i < n; i++)
        for (j = 0; j < 4; j++)
            c++;
    for (k = 1; k < n; k *= 2)
        c++;
    return c;
}

다음 C 프로그램의 실행 결과와, n이 커질 때 c++가 실행되는 횟수를 빅오 표기로 나타낸 것을 바르게 짝지은 것은? (단, 로그의 밑은 2이다)

[코드]
#include <stdio.h>
int main(void) {
    int n = 20, c = 0, i, j;
    for (i = 1; i <= n; i++)
        for (j = 1; j < n; j *= 2)
            c++;
    printf("%d", c);
    return 0;
}

다음 C 함수 g를 g(n)으로 부를 때 s++가 실행되는 전체 횟수를 빅오 표기로 나타낸 것은? (단, n은 2의 거듭제곱이다)

[자료]
int g(int n) {
    int i, s = 0;
    if (n <= 1)
        return 1;
    for (i = 0; i < n; i++)
        s++;
    return s + g(n / 2);
}

다음 파이썬(Python) 프로그램의 실행 결과는?

[코드]
class Node:
    def __init__(self, key, left=None, right=None):
        self.key = key
        self.left = left
        self.right = right

def size(t):
    if t is None:
        return 0
    return 1 + size(t.left) + size(t.right)

def height(t):
    if t is None:
        return 0
    return 1 + max(height(t.left), height(t.right))

def leaf(t):
    if t is None:
        return 0
    if t.left is None and t.right is None:
        return 1
    return leaf(t.left) + leaf(t.right)

a = Node(20, Node(10), Node(30, Node(25)))
b = Node(70, None, Node(90, Node(80)))
root = Node(50, a, b)
print(size(root), height(root), leaf(root))

다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
struct node {
    char op;
    int val;
    struct node *left, *right;
};
struct node a = {' ', 9, NULL, NULL}, b = {' ', 4, NULL, NULL};
struct node c = {' ', 3, NULL, NULL}, d = {' ', 2, NULL, NULL};
struct node e = {'-', 0, &a, &b}, f = {'+', 0, &c, &d};
struct node g = {'*', 0, &e, &f};
int calc(struct node *p) {
    int x, y;
    if (p->left == NULL && p->right == NULL)
        return p->val;
    x = calc(p->left);
    y = calc(p->right);
    if (p->op == '+') return x + y;
    if (p->op == '-') return x - y;
    return x * y;
}
int main(void) {
    printf("%d", calc(&g));
    return 0;
}

다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
int main(void) {
    int a[6] = {4, 2, 7, 1, 8, 5};
    int i, j, t, pass;
    for (pass = 1; pass <= 2; pass++)
        for (j = 0; j < 6 - pass; j++)
            if (a[j] < a[j + 1]) {
                t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
            }
    for (i = 0; i < 6; i++)
        printf("%d ", a[i]);
    return 0;
}

